CREATE FUNCTION operativa_stz.stz_budget_frozen() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF OLD.status='APROBADO' THEN RAISE EXCEPTION '%', 'El presupuesto aprobado es inmutable; crea una revisión'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_budget_frozen BEFORE UPDATE ON operativa_stz.stz_budgets FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_budget_frozen();

CREATE FUNCTION operativa_stz.stz_budget_approve() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='APROBADO' AND (NOT EXISTS(SELECT 1 FROM stz_items WHERE budget_id=NEW.id) OR length(trim(NEW.reference))=0 OR NEW.approved_on IS NULL) THEN RAISE EXCEPTION '%', 'Presupuesto sin partidas o referencia de aprobación'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_budget_approve BEFORE UPDATE ON operativa_stz.stz_budgets FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_budget_approve();

CREATE FUNCTION operativa_stz.stz_item_frozen_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT status FROM stz_budgets WHERE id=NEW.budget_id)<>'BORRADOR' THEN RAISE EXCEPTION '%', 'Las partidas aprobadas son inmutables'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_item_frozen_insert BEFORE INSERT ON operativa_stz.stz_items FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_item_frozen_insert();

CREATE FUNCTION operativa_stz.stz_item_scope_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT id_proyecto FROM actuaciones WHERE id_actuacion=NEW.action_id)<>(SELECT project_id FROM stz_budgets WHERE id=NEW.budget_id) OR (NEW.contract_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stz_contract_projects cp JOIN stz_budgets b ON b.project_id=cp.project_id WHERE b.id=NEW.budget_id AND cp.contract_id=NEW.contract_id)) THEN RAISE EXCEPTION '%', 'Partida fuera del proyecto o contrato no vinculado'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_item_scope_insert BEFORE INSERT ON operativa_stz.stz_items FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_item_scope_insert();

CREATE FUNCTION operativa_stz.stz_item_frozen_update() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT status FROM stz_budgets WHERE id=NEW.budget_id)<>'BORRADOR' THEN RAISE EXCEPTION '%', 'Las partidas aprobadas son inmutables'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_item_frozen_update BEFORE UPDATE ON operativa_stz.stz_items FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_item_frozen_update();

CREATE FUNCTION operativa_stz.stz_item_scope_update() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT id_proyecto FROM actuaciones WHERE id_actuacion=NEW.action_id)<>(SELECT project_id FROM stz_budgets WHERE id=NEW.budget_id) OR (NEW.contract_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stz_contract_projects cp JOIN stz_budgets b ON b.project_id=cp.project_id WHERE b.id=NEW.budget_id AND cp.contract_id=NEW.contract_id)) THEN RAISE EXCEPTION '%', 'Partida fuera del proyecto o contrato no vinculado'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_item_scope_update BEFORE UPDATE ON operativa_stz.stz_items FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_item_scope_update();

CREATE FUNCTION operativa_stz.stz_item_frozen_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT status FROM stz_budgets WHERE id=OLD.budget_id)<>'BORRADOR' THEN RAISE EXCEPTION '%', 'Las partidas aprobadas son inmutables'; END IF; RETURN OLD; END $$;
CREATE TRIGGER stz_item_frozen_delete BEFORE DELETE ON operativa_stz.stz_items FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_item_frozen_delete();

CREATE FUNCTION operativa_stz.stz_measure_approved() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT b.status FROM stz_items i JOIN stz_budgets b ON b.id=i.budget_id WHERE i.id=NEW.item_id)<>'APROBADO' OR (SELECT b.revision FROM stz_items i JOIN stz_budgets b ON b.id=i.budget_id WHERE i.id=NEW.item_id)<>(SELECT max(b2.revision) FROM stz_budgets b2 WHERE b2.status='APROBADO' AND b2.project_id=(SELECT b.project_id FROM stz_items i JOIN stz_budgets b ON b.id=i.budget_id WHERE i.id=NEW.item_id)) THEN RAISE EXCEPTION '%', 'Mide contra la última revisión aprobada'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_measure_approved BEFORE INSERT ON operativa_stz.stz_measurements FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_measure_approved();

CREATE FUNCTION operativa_stz.stz_measure_ceiling() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.quantity_milli + coalesce((SELECT sum(m.quantity_milli) FROM stz_measurements m JOIN stz_items oi ON oi.id=m.item_id JOIN stz_budgets ob ON ob.id=oi.budget_id JOIN stz_items ni ON ni.id=NEW.item_id JOIN stz_budgets nb ON nb.id=ni.budget_id WHERE ob.project_id=nb.project_id AND oi.code=ni.code),0)>(SELECT quantity_milli FROM stz_items WHERE id=NEW.item_id) THEN RAISE EXCEPTION '%', 'La medición supera la cantidad autorizada; revisa el presupuesto'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_measure_ceiling BEFORE INSERT ON operativa_stz.stz_measurements FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_measure_ceiling();

CREATE FUNCTION operativa_stz.stz_measure_no_update() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF true THEN RAISE EXCEPTION '%', 'La medición conserva su evidencia original'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_measure_no_update BEFORE UPDATE ON operativa_stz.stz_measurements FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_measure_no_update();

CREATE FUNCTION operativa_stz.stz_measure_no_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF EXISTS(SELECT 1 FROM stz_certificate_lines WHERE measurement_id=OLD.id) THEN RAISE EXCEPTION '%', 'No se puede anular una medición certificada'; END IF; RETURN OLD; END $$;
CREATE TRIGGER stz_measure_no_delete BEFORE DELETE ON operativa_stz.stz_measurements FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_measure_no_delete();

CREATE FUNCTION operativa_stz.stz_cert_line_scope() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT status FROM stz_certificates WHERE id=NEW.certificate_id)<>'BORRADOR' OR NOT EXISTS(SELECT 1 FROM stz_measurements m JOIN stz_items i ON i.id=m.item_id JOIN stz_budgets b ON b.id=i.budget_id JOIN stz_certificates c ON c.id=NEW.certificate_id WHERE m.id=NEW.measurement_id AND c.project_id=b.project_id AND c.contract_id=i.contract_id AND m.measured_on BETWEEN c.period_start AND c.period_end) THEN RAISE EXCEPTION '%', 'Medición incompatible con proyecto, contrato, periodo o estado de certificación'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_cert_line_scope BEFORE INSERT ON operativa_stz.stz_certificate_lines FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_cert_line_scope();

CREATE FUNCTION operativa_stz.stz_cert_frozen() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF OLD.status='VALIDADA' THEN RAISE EXCEPTION '%', 'La certificación validada es inmutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_cert_frozen BEFORE UPDATE ON operativa_stz.stz_certificates FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_cert_frozen();

CREATE FUNCTION operativa_stz.stz_cert_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='VALIDADA' AND (NOT EXISTS(SELECT 1 FROM stz_certificate_lines WHERE certificate_id=NEW.id) OR length(trim(NEW.reference))=0) THEN RAISE EXCEPTION '%', 'Certificación sin mediciones o evidencia'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_cert_validate BEFORE UPDATE ON operativa_stz.stz_certificates FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_cert_validate();

CREATE FUNCTION operativa_stz.stz_plan_scope_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM stz_assets a JOIN proyecto_emplazamientos pe ON pe.id_emplazamiento=a.location_id WHERE a.id=NEW.asset_id AND pe.id_proyecto=NEW.project_id) OR (NEW.contract_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stz_contract_projects WHERE contract_id=NEW.contract_id AND project_id=NEW.project_id)) THEN RAISE EXCEPTION '%', 'Activo o contrato fuera del ámbito del proyecto'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_plan_scope_insert BEFORE INSERT ON operativa_stz.stz_plans FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_plan_scope_insert();

CREATE FUNCTION operativa_stz.stz_plan_scope_update() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM stz_assets a JOIN proyecto_emplazamientos pe ON pe.id_emplazamiento=a.location_id WHERE a.id=NEW.asset_id AND pe.id_proyecto=NEW.project_id) OR (NEW.contract_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stz_contract_projects WHERE contract_id=NEW.contract_id AND project_id=NEW.project_id)) THEN RAISE EXCEPTION '%', 'Activo o contrato fuera del ámbito del proyecto'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_plan_scope_update BEFORE UPDATE ON operativa_stz.stz_plans FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_plan_scope_update();

CREATE FUNCTION operativa_stz.stz_order_scope_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM stz_assets a JOIN proyecto_emplazamientos pe ON pe.id_emplazamiento=a.location_id WHERE a.id=NEW.asset_id AND pe.id_proyecto=NEW.project_id) OR (NEW.contract_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stz_contract_projects WHERE contract_id=NEW.contract_id AND project_id=NEW.project_id)) THEN RAISE EXCEPTION '%', 'Activo o contrato fuera del ámbito del proyecto'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_order_scope_insert BEFORE INSERT ON operativa_stz.stz_orders FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_order_scope_insert();

CREATE FUNCTION operativa_stz.stz_order_scope_update() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM stz_assets a JOIN proyecto_emplazamientos pe ON pe.id_emplazamiento=a.location_id WHERE a.id=NEW.asset_id AND pe.id_proyecto=NEW.project_id) OR (NEW.contract_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stz_contract_projects WHERE contract_id=NEW.contract_id AND project_id=NEW.project_id)) THEN RAISE EXCEPTION '%', 'Activo o contrato fuera del ámbito del proyecto'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_order_scope_update BEFORE UPDATE ON operativa_stz.stz_orders FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_order_scope_update();

CREATE FUNCTION operativa_stz.stz_order_close() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='CERRADA' AND (OLD.status<>'PENDIENTE_VALIDACION' OR NEW.finished_on IS NULL OR length(trim(NEW.result))=0 OR length(trim(NEW.evidence))=0 OR NEW.checked_by IS NULL) THEN RAISE EXCEPTION '%', 'El cierre requiere ejecución, resultado, evidencia y validación'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_order_close BEFORE UPDATE ON operativa_stz.stz_orders FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_order_close();

CREATE FUNCTION operativa_stz.stz_resource_frozen_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT status FROM stz_orders WHERE id=NEW.order_id)='CERRADA' THEN RAISE EXCEPTION '%', 'Reabre la orden antes de modificar sus recursos'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_resource_frozen_insert BEFORE INSERT ON operativa_stz.stz_resources FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_resource_frozen_insert();

CREATE FUNCTION operativa_stz.stz_resource_frozen_update() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT status FROM stz_orders WHERE id=NEW.order_id)='CERRADA' THEN RAISE EXCEPTION '%', 'Reabre la orden antes de modificar sus recursos'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_resource_frozen_update BEFORE UPDATE ON operativa_stz.stz_resources FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_resource_frozen_update();

CREATE FUNCTION operativa_stz.stz_resource_frozen_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT status FROM stz_orders WHERE id=OLD.order_id)='CERRADA' THEN RAISE EXCEPTION '%', 'Reabre la orden antes de modificar sus recursos'; END IF; RETURN OLD; END $$;
CREATE TRIGGER stz_resource_frozen_delete BEFORE DELETE ON operativa_stz.stz_resources FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_resource_frozen_delete();

CREATE FUNCTION operativa_stz.stz_invoice_frozen() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF OLD.status='REGISTRADA' THEN RAISE EXCEPTION '%', 'La factura registrada es inmutable; registra una rectificativa'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_invoice_frozen BEFORE UPDATE ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_invoice_frozen();

CREATE FUNCTION operativa_stz.stz_invoice_correction() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.original_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stz_invoices o WHERE o.id=NEW.original_id AND o.original_id IS NULL AND o.status='REGISTRADA' AND o.project_id=NEW.project_id AND o.contract_id IS NOT DISTINCT FROM NEW.contract_id) THEN RAISE EXCEPTION '%', 'Rectificativa sin factura original compatible'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_invoice_correction BEFORE INSERT ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_invoice_correction();

CREATE FUNCTION operativa_stz.stz_invoice_line() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF (SELECT status FROM stz_invoices WHERE id=NEW.invoice_id)<>'BORRADOR' OR NOT EXISTS(SELECT 1 FROM stz_invoices f WHERE f.id=NEW.invoice_id AND ((NEW.certificate_id IS NOT NULL AND EXISTS(SELECT 1 FROM stz_certificates c WHERE c.id=NEW.certificate_id AND c.status='VALIDADA' AND c.project_id=f.project_id AND c.contract_id=f.contract_id)) OR (NEW.order_id IS NOT NULL AND EXISTS(SELECT 1 FROM stz_orders o WHERE o.id=NEW.order_id AND o.status='CERRADA' AND o.project_id=f.project_id AND o.contract_id IS NOT DISTINCT FROM f.contract_id)))) OR ((SELECT original_id FROM stz_invoices WHERE id=NEW.invoice_id) IS NULL AND (NEW.base_cents<=0 OR NEW.vat_cents<0)) OR ((SELECT original_id FROM stz_invoices WHERE id=NEW.invoice_id) IS NOT NULL AND (NEW.base_cents>=0 OR NEW.vat_cents>0)) THEN RAISE EXCEPTION '%', 'Línea incompatible: verifica fuente validada, proyecto, contrato y signo'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_invoice_line BEFORE INSERT ON operativa_stz.stz_invoice_lines FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_invoice_line();

CREATE FUNCTION operativa_stz.stz_invoice_has_lines() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='REGISTRADA' AND (NOT EXISTS(SELECT 1 FROM stz_invoice_lines WHERE invoice_id=NEW.id) OR length(trim(NEW.reference))=0) THEN RAISE EXCEPTION '%', 'Factura sin líneas o referencia documental'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_invoice_has_lines BEFORE UPDATE ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_invoice_has_lines();

CREATE FUNCTION operativa_stz.stz_invoice_cert_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='REGISTRADA' AND EXISTS(SELECT 1 FROM stz_invoice_lines nl WHERE nl.invoice_id=NEW.id AND nl.certificate_id IS NOT NULL AND ((SELECT coalesce(sum(il.base_cents),0) FROM stz_invoice_lines il JOIN stz_invoices f ON f.id=il.invoice_id WHERE il.certificate_id=nl.certificate_id AND (f.status='REGISTRADA' OR f.id=NEW.id))>(SELECT coalesce(sum((m.quantity_milli*i.unit_cents+500)/1000),0) FROM stz_certificate_lines cl JOIN stz_measurements m ON m.id=cl.measurement_id JOIN stz_items i ON i.id=m.item_id WHERE cl.certificate_id=nl.certificate_id) OR (SELECT coalesce(sum(il.base_cents),0) FROM stz_invoice_lines il JOIN stz_invoices f ON f.id=il.invoice_id WHERE il.certificate_id=nl.certificate_id AND (f.status='REGISTRADA' OR f.id=NEW.id))<0)) THEN RAISE EXCEPTION '%', 'El importe facturado excede la certificación o la rectifica por debajo de cero'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_invoice_cert_limit BEFORE UPDATE ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_invoice_cert_limit();

CREATE FUNCTION operativa_stz.stz_invoice_contract_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='REGISTRADA' AND NEW.contract_id IS NOT NULL AND (SELECT coalesce(sum(il.base_cents),0) FROM stz_invoice_lines il JOIN stz_invoices f ON f.id=il.invoice_id WHERE f.contract_id=NEW.contract_id AND (f.status='REGISTRADA' OR f.id=NEW.id))>(SELECT base_cents FROM stz_contracts WHERE id=NEW.contract_id) THEN RAISE EXCEPTION '%', 'Se supera el importe del contrato compartido; registra su modificación autorizada'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_invoice_contract_limit BEFORE UPDATE ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_invoice_contract_limit();

CREATE FUNCTION operativa_stz.stz_invoice_credit_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='REGISTRADA' AND NEW.original_id IS NOT NULL AND (SELECT coalesce(sum(il.base_cents+il.vat_cents),0) FROM stz_invoice_lines il JOIN stz_invoices f ON f.id=il.invoice_id WHERE (f.id=NEW.original_id OR f.original_id=NEW.original_id) AND (f.status='REGISTRADA' OR f.id=NEW.id))<0 THEN RAISE EXCEPTION '%', 'La rectificación supera el importe de la factura original'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_invoice_credit_limit BEFORE UPDATE ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_invoice_credit_limit();

CREATE FUNCTION operativa_stz.stz_payment_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM stz_invoices WHERE id=NEW.invoice_id AND original_id IS NULL AND status='REGISTRADA') OR coalesce((SELECT sum(amount_cents) FROM stz_payments WHERE invoice_id=NEW.invoice_id),0)+NEW.amount_cents<0 OR (NEW.amount_cents>0 AND coalesce((SELECT sum(amount_cents) FROM stz_payments WHERE invoice_id=NEW.invoice_id),0)+NEW.amount_cents>(SELECT coalesce(sum(l.base_cents+l.vat_cents),0) FROM stz_invoice_lines l JOIN stz_invoices f ON f.id=l.invoice_id WHERE (f.id=NEW.invoice_id OR f.original_id=NEW.invoice_id) AND f.status='REGISTRADA')) THEN RAISE EXCEPTION '%', 'Pago incompatible o superior al saldo de la factura'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_payment_limit BEFORE INSERT ON operativa_stz.stz_payments FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_payment_limit();

