CREATE FUNCTION operativa_stz.stz_forecasts_update_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF true THEN RAISE EXCEPTION '%', 'Este registro conserva su historial; usa una operación compensatoria'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_forecasts_update_immutable BEFORE UPDATE ON operativa_stz.stz_forecasts FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_forecasts_update_immutable();

CREATE FUNCTION operativa_stz.stz_forecasts_delete_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF true THEN RAISE EXCEPTION '%', 'Este registro conserva su historial; usa una operación compensatoria'; END IF; RETURN OLD; END $$;
CREATE TRIGGER stz_forecasts_delete_immutable BEFORE DELETE ON operativa_stz.stz_forecasts FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_forecasts_delete_immutable();

CREATE FUNCTION operativa_stz.stz_audit_update_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF true THEN RAISE EXCEPTION '%', 'Este registro conserva su historial; usa una operación compensatoria'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_audit_update_immutable BEFORE UPDATE ON operativa_stz.stz_audit FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_audit_update_immutable();

CREATE FUNCTION operativa_stz.stz_audit_delete_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF true THEN RAISE EXCEPTION '%', 'Este registro conserva su historial; usa una operación compensatoria'; END IF; RETURN OLD; END $$;
CREATE TRIGGER stz_audit_delete_immutable BEFORE DELETE ON operativa_stz.stz_audit FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_audit_delete_immutable();

CREATE FUNCTION operativa_stz.stz_revision_measured() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='APROBADO' AND EXISTS(SELECT oi.code FROM stz_measurements m JOIN stz_items oi ON oi.id=m.item_id JOIN stz_budgets b ON b.id=oi.budget_id WHERE b.project_id=NEW.project_id GROUP BY oi.code HAVING sum(m.quantity_milli)>coalesce((SELECT ni.quantity_milli FROM stz_items ni WHERE ni.budget_id=NEW.id AND ni.code=oi.code),0)) THEN RAISE EXCEPTION '%', 'La revisión debe conservar las partidas y cantidades ya medidas'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_revision_measured BEFORE UPDATE ON operativa_stz.stz_budgets FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_revision_measured();

CREATE FUNCTION operativa_stz.stz_revision_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='APROBADO' AND EXISTS(SELECT 1 FROM stz_items n JOIN stz_items o ON o.code=n.code JOIN stz_budgets b ON b.id=o.budget_id WHERE n.budget_id=NEW.id AND b.project_id=NEW.project_id AND b.status='APROBADO' AND EXISTS(SELECT 1 FROM stz_measurements m WHERE m.item_id=o.id) AND (n.unit<>o.unit OR n.action_id<>o.action_id OR n.contract_id IS DISTINCT FROM o.contract_id)) THEN RAISE EXCEPTION '%', 'La partida medida conserva unidad, actuación y contrato'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_revision_identity BEFORE UPDATE ON operativa_stz.stz_budgets FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_revision_identity();

CREATE FUNCTION operativa_stz.stz_contract_reduction() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.end_on<NEW.start_on OR NEW.base_cents<(SELECT coalesce(sum(l.base_cents),0) FROM stz_invoice_lines l JOIN stz_invoices f ON f.id=l.invoice_id WHERE f.contract_id=NEW.id AND f.status='REGISTRADA') THEN RAISE EXCEPTION '%', 'Modificación incompatible con fechas o importe ya facturado'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_contract_reduction BEFORE UPDATE ON operativa_stz.stz_contracts FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_contract_reduction();

CREATE FUNCTION operativa_stz.stz_credit_source() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF EXISTS(SELECT 1 FROM stz_invoices f WHERE f.id=NEW.invoice_id AND f.original_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stz_invoice_lines o WHERE o.invoice_id=f.original_id AND o.certificate_id IS NOT DISTINCT FROM NEW.certificate_id AND o.order_id IS NOT DISTINCT FROM NEW.order_id)) THEN RAISE EXCEPTION '%', 'La rectificativa debe referirse a una fuente de la factura original'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_credit_source BEFORE INSERT ON operativa_stz.stz_invoice_lines FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_credit_source();

CREATE FUNCTION operativa_stz.stz_order_billing_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='REGISTRADA' AND EXISTS(SELECT 1 FROM stz_invoice_lines nl WHERE nl.invoice_id=NEW.id AND nl.order_id IS NOT NULL AND ((SELECT coalesce(sum(l.base_cents),0) FROM stz_invoice_lines l JOIN stz_invoices f ON f.id=l.invoice_id WHERE l.order_id=nl.order_id AND (f.status='REGISTRADA' OR f.id=NEW.id))<0 OR (SELECT coalesce(sum(l.base_cents),0) FROM stz_invoice_lines l JOIN stz_invoices f ON f.id=l.invoice_id WHERE l.order_id=nl.order_id AND (f.status='REGISTRADA' OR f.id=NEW.id))>(SELECT coalesce(sum((quantity_milli*unit_cents+500)/1000),0) FROM stz_resources WHERE order_id=nl.order_id))) THEN RAISE EXCEPTION '%', 'La facturación de la orden supera sus recursos registrados o queda negativa'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_order_billing_limit BEFORE UPDATE ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_order_billing_limit();

CREATE FUNCTION operativa_stz.stz_certificate_vat_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.status='REGISTRADA' AND EXISTS(SELECT 1 FROM stz_invoice_lines nl WHERE nl.invoice_id=NEW.id AND nl.certificate_id IS NOT NULL AND ((SELECT coalesce(sum(l.vat_cents),0) FROM stz_invoice_lines l JOIN stz_invoices f ON f.id=l.invoice_id WHERE l.certificate_id=nl.certificate_id AND (f.status='REGISTRADA' OR f.id=NEW.id))<0 OR (SELECT coalesce(sum(l.vat_cents),0) FROM stz_invoice_lines l JOIN stz_invoices f ON f.id=l.invoice_id WHERE l.certificate_id=nl.certificate_id AND (f.status='REGISTRADA' OR f.id=NEW.id))>(SELECT coalesce(sum((((m.quantity_milli*i.unit_cents+500)/1000)*i.vat_bps+5000)/10000),0) FROM stz_certificate_lines cl JOIN stz_measurements m ON m.id=cl.measurement_id JOIN stz_items i ON i.id=m.item_id WHERE cl.certificate_id=nl.certificate_id))) THEN RAISE EXCEPTION '%', 'IVA acumulado incompatible con la certificación'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_certificate_vat_limit BEFORE UPDATE ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_certificate_vat_limit();

CREATE FUNCTION operativa_stz.stz_order_vat_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.order_id IS NOT NULL AND abs(NEW.vat_cents) > (abs(NEW.base_cents)*coalesce((SELECT c.vat_bps FROM stz_invoices f JOIN stz_contracts c ON c.id=f.contract_id WHERE f.id=NEW.invoice_id),2100)+5000)/10000 THEN RAISE EXCEPTION '%', 'IVA superior al tipo del contrato de mantenimiento'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_order_vat_limit BEFORE INSERT ON operativa_stz.stz_invoice_lines FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_order_vat_limit();

CREATE FUNCTION operativa_stz.stz_payment_date() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.paid_on<(SELECT issued_on FROM stz_invoices WHERE id=NEW.invoice_id) OR NEW.amount_cents=0 THEN RAISE EXCEPTION '%', 'Fecha o importe de pago no válido'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_payment_date BEFORE INSERT ON operativa_stz.stz_payments FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_payment_date();

CREATE FUNCTION operativa_stz.stz_receipt_dates() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF NEW.corrected_on IS NOT NULL AND (NEW.result<>'CON_DEFECTOS' OR NEW.corrected_on<NEW.received_on) THEN RAISE EXCEPTION '%', 'Subsanación incompatible con la recepción'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_receipt_dates BEFORE UPDATE ON operativa_stz.stz_receipts FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_receipt_dates();

CREATE FUNCTION operativa_stz.stz_invoice_legacy_dup() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF EXISTS(SELECT 1 FROM gastos WHERE numero_factura=NEW.code) THEN RAISE EXCEPTION '%', 'Esta factura ya está registrada como gasto simple'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_invoice_legacy_dup BEFORE INSERT ON operativa_stz.stz_invoices FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_invoice_legacy_dup();

CREATE FUNCTION operativa_stz.stz_legacy_invoice_dup() RETURNS trigger LANGUAGE plpgsql SET search_path=operativa_stz,app_stz,pg_catalog AS $$ BEGIN IF EXISTS(SELECT 1 FROM stz_invoices WHERE code=NEW.numero_factura) THEN RAISE EXCEPTION '%', 'Esta factura ya existe en el control operativo'; END IF; RETURN NEW; END $$;
CREATE TRIGGER stz_legacy_invoice_dup BEFORE INSERT ON economico.gastos_ficha FOR EACH ROW EXECUTE FUNCTION operativa_stz.stz_legacy_invoice_dup();
